+  const isExtended = (tip, mcp) => {
+    if (!landmarks[tip] || !landmarks[mcp]) {
+      return false;
+    }
+
+    return getDistance(landmarks[tip], wrist) > getDistance(landmarks[mcp], wrist) * 1.15;
